import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Responsive, WidthProvider } from 'react-grid-layout';
import { Grid, Button, TextField, IconButton } from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import DraggableResizableImage from './DraggableResizableImage';
import ReactSelect from 'react-select';
import csvData from './ExpData.csv';
import 'react-grid-layout/css/styles.css';
import 'react-resizable/css/styles.css';

const ResponsiveGridLayout = WidthProvider(Responsive);

const Heatmap = ({ data, setData }) => {
  const [csvDataState, setCsvDataState] = useState({ x: [], y: [], z: {} });
  const [zOptions, setZOptions] = useState([]);
  const [layoutName, setLayoutName] = useState('');

  // Use data from props or default values
  const selectedZ = useMemo(() => data.selectedZ || [], [data.selectedZ]);
  const savedLayouts = useMemo(() => data.savedLayouts || [], [data.savedLayouts]);
  const selectedLayout = useMemo(() => data.selectedLayout || '', [data.selectedLayout]);
  const layouts = useMemo(() => data.layouts || { lg: [] }, [data.layouts]);

  const parseCSV = useCallback((csvData) => {
    const rows = csvData.split('\n').map(row => row.split(','));
    const headers = rows[0];
    const dataRows = rows.slice(1).filter(row => row.length === headers.length);
    return { headers, rows: dataRows };
  }, []);

  const loadData = useCallback(() => {
    fetch(csvData)
      .then(response => response.text())
      .then(csv => {
        const { headers, rows } = parseCSV(csv);
        const desalIndex = headers.indexOf('Desal 1 base cost');
        const disposalIndex = headers.indexOf('Disposal cost');

        const xValues = new Set();
        const yValues = new Set();
        const zData = {};
        headers.slice(2).forEach(header => {
          zData[header] = [];
        });

        rows.forEach(row => {
          const xValue = parseFloat(row[desalIndex]);
          const yValue = parseFloat(row[disposalIndex]);

          xValues.add(xValue);
          if (yValue >= 1 && yValue <= 5) {
            yValues.add(yValue);
            headers.slice(2).forEach((header, index) => {
              if (!zData[header]) zData[header] = [];
              zData[header].push({ x: xValue, y: yValue, value: parseFloat(row[index + 2]) });
            });
          }
        });

        const uniqueX = Array.from(xValues);
        const uniqueY = Array.from(yValues);

        Object.keys(zData).forEach(header => {
          const zMatrix = Array.from({ length: uniqueY.length }, () => Array(uniqueX.length).fill(null));
          zData[header].forEach(point => {
            const xIndex = uniqueX.indexOf(point.x);
            const yIndex = uniqueY.indexOf(point.y);
            if (xIndex !== -1 && yIndex !== -1) {
              zMatrix[yIndex][xIndex] = point.value;
            }
          });
          zData[header] = zMatrix;
        });

        setCsvDataState({ x: uniqueX, y: uniqueY, z: zData });
        setZOptions(headers.slice(2).map(option => ({ value: option, label: option })));
      });
  }, [parseCSV]);

  useEffect(() => {
    if (selectedZ.length === 0) {
      loadData();
    }
  }, [loadData, selectedZ]);

  const findFirstAvailableSpot = useCallback((layout) => {
    const occupiedPositions = new Set(layout.map(item => `${item.x},${item.y}`));
    const cols = 12; // Number of columns in the grid
    const rows = 10; // Arbitrary limit for the number of rows to check
    let maxY = 0;

    for (let x = 0; x < cols; x++) {
      for (let y = 0; y <= maxY; y++) {
        if (!occupiedPositions.has(`${x},${y}`)) {
          return { x, y };
        }
      }
      maxY++;
    }

    return { x: 0, y: maxY }; // Default to placing the item at the bottom if no space is found
  }, []);

  const handleZChange = useCallback((selectedOptions) => {
    const newZ = selectedOptions.map(option => option.value);
    const newZKeys = newZ.filter(z => !selectedZ.includes(z));
    
    const newLayouts = { ...layouts };
    newZKeys.forEach((zKey, index) => {
      const position = findFirstAvailableSpot(newLayouts.lg);
      newLayouts.lg.push({
        i: `box-${selectedZ.length + index}`,
        x: position.x,
        y: position.y,
        w: 8, 
        h: 8, 
      });
    });

    setData(prevData => ({
      ...prevData,
      selectedZ: newZ,
      layouts: newLayouts
    }));
  }, [selectedZ, layouts, setData, findFirstAvailableSpot]);

  const handleSaveLayout = useCallback(() => {
    if (layoutName.trim() !== '') {
      setData(prevData => ({
        ...prevData,
        savedLayouts: [
          ...prevData.savedLayouts,
          { name: layoutName, layout: layouts.lg }
        ]
      }));
      setLayoutName('');
    }
  }, [layoutName, layouts, setData]);

  const handleLayoutSelect = useCallback((event) => {
    const selected = event.target.value;
    const layout = savedLayouts.find(layout => layout.name === selected);
    if (layout) {
      setData(prevData => ({
        ...prevData,
        selectedLayout: selected,
        layouts: { lg: layout.layout }
      }));
    }
  }, [savedLayouts, setData]);

  const handleDeleteLayout = useCallback((name) => {
    setData(prevData => ({
      ...prevData,
      savedLayouts: prevData.savedLayouts.filter(layout => layout.name !== name),
      selectedLayout: prevData.selectedLayout === name ? '' : prevData.selectedLayout,
      layouts: prevData.selectedLayout === name ? { lg: [] } : prevData.layouts
    }));
  }, [setData]);

  const onLayoutChange = useCallback((newLayout) => {
    setData(prevData => ({
      ...prevData,
      layouts: { lg: newLayout }
    }));
  }, [setData]);

  return (
    <div>
      <Grid container spacing={2} alignItems="center" justifyContent="flex-start">
        <Grid item>
          <ReactSelect
            isMulti
            options={zOptions}
            value={selectedZ.map(z => ({ value: z, label: z }))}
            onChange={handleZChange}
          />
        </Grid>
        <Grid item>
          <TextField
            label="Layout Name"
            value={layoutName}
            onChange={(e) => setLayoutName(e.target.value)}
            variant="outlined"
            style={{ margin: '16px', minWidth: '200px' }}
          />
        </Grid>
        <Grid item>
          <Button variant="contained" color="primary" onClick={handleSaveLayout} style={{ margin: '16px' }}>
            Save Layout
          </Button>
        </Grid>
        <Grid item>
          <ReactSelect
            options={savedLayouts.map(layout => ({ value: layout.name, label: layout.name }))}
            value={selectedLayout ? { value: selectedLayout, label: selectedLayout } : null}
            onChange={option => handleLayoutSelect({ target: { value: option.value } })}
          />
          {savedLayouts.map(layout => (
            <IconButton key={layout.name} onClick={() => handleDeleteLayout(layout.name)} size="small">
              <DeleteIcon />
            </IconButton>
          ))}
        </Grid>
      </Grid>
      <ResponsiveGridLayout
        className="layout"
        layouts={layouts}
        breakpoints={{ lg: 1200, md: 996, sm: 768, xs: 480, xxs: 0 }}
        cols={{ lg: 12, md: 10, sm: 6, xs: 4, xxs: 2 }}
        rowHeight={30}
        onLayoutChange={onLayoutChange}
        onResizeStop={onLayoutChange}
        onDragStop={onLayoutChange}
        draggableHandle=".handle"
        isResizable={true}
        isDraggable={true}
      >
        {selectedZ.map((zKey, index) => (
          <div key={`box-${index}`} data-grid={layouts.lg[index]}>
            <div className="handle" style={{ width: '100%', height: '100%' }}>
              <DraggableResizableImage
                data={[
                  {
                    x: csvDataState.x,
                    y: csvDataState.y,
                    z: csvDataState.z[zKey] || [],
                    type: 'heatmap',
                    colorscale: 'Viridis',
                    colorbar: {
                      title: zKey,
                      titleside: 'right'
                    }
                  },
                ]}
                layout={{
                  title: zKey,
                  xaxis: { title: 'Desal 1 base cost' },
                  yaxis: { title: 'Disposal cost' },
                  autosize: true,
                  margin: { t: 50, b: 50, l: 50, r: 50 },
                }}
                style={{ width: '100%', height: '100%' }}
              />
            </div>
          </div>
        ))}
      </ResponsiveGridLayout>
    </div>
  );
};

export default Heatmap;