import React, { useState, useEffect } from 'react';
import Heatmap from './Heatmap'; // Ensure this matches the file name exactly
import ParallelCoordinatesPlot from './ParallelCoordinatesPlot'; // Ensure this matches the file name exactly
import { Container, FormControl, MenuItem, Select, IconButton } from '@mui/material';
import DownloadIcon from '@mui/icons-material/Download';

function App() {
  const [visualizationType, setVisualizationType] = useState('heatmap');
  const [heatmapData, setHeatmapData] = useState({
    selectedZ: [],
    layouts: { lg: [] },
    savedLayouts: [],
    selectedLayout: ''
  });
  const [parallelCoordData, setParallelCoordData] = useState({
    savedLayouts: [],
    selectedLayout: '',
    dimensions: [],
    selectedColumns: []
  });

  useEffect(() => {
    const savedData = JSON.parse(localStorage.getItem('visualizationData'));
    if (savedData) {
      setHeatmapData(savedData.heatmap || heatmapData);
      setParallelCoordData(savedData.parallelCoord || parallelCoordData);
    }
  }, []);

  useEffect(() => {
    const dataToSave = {
      heatmap: heatmapData,
      parallelCoord: parallelCoordData
    };
    localStorage.setItem('visualizationData', JSON.stringify(dataToSave));
  }, [heatmapData, parallelCoordData]);

  const handleVisualizationTypeChange = (event) => {
    setVisualizationType(event.target.value);
  };

  const downloadData = () => {
    const dataStr = JSON.stringify({
      heatmap: heatmapData,
      parallelCoord: parallelCoordData
    });
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.download = 'visualization_data.json';
    link.href = url;
    link.click();
  };

  return (
    <Container>
      <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: '16px' }}>
        <IconButton onClick={downloadData} color="primary">
          <DownloadIcon />
        </IconButton>
      </div>
      <FormControl fullWidth margin="normal">
        <Select
          value={visualizationType}
          onChange={handleVisualizationTypeChange}
          displayEmpty
        >
          <MenuItem value="heatmap">Heatmap</MenuItem>
          <MenuItem value="parallelCoordinatesPlot">Parallel Coordinate Plot</MenuItem>
        </Select>
      </FormControl>
      {visualizationType === 'heatmap' && (
        <Heatmap data={heatmapData} setData={setHeatmapData} />
      )}
      {visualizationType === 'parallelCoordinatesPlot' && (
        <ParallelCoordinatesPlot data={parallelCoordData} setData={setParallelCoordData} />
      )}
    </Container>
  );
}

export default App;
