import React, { useState, useEffect, useCallback } from 'react';
import Plot from 'react-plotly.js';
import { Grid, TextField } from '@mui/material';
import ReactSelect from 'react-select';
import csvData from './ExpData.csv';

const ParallelCoordinatesPlot = ({ data, setData }) => {
  const [plotData, setPlotData] = useState([]);
  const [dimensions, setDimensions] = useState(data.dimensions || []);
  const [layoutName, setLayoutName] = useState('');
  const [savedLayouts, setSavedLayouts] = useState(data.savedLayouts || []);
  const [selectedLayout, setSelectedLayout] = useState(data.selectedLayout || '');
  const [selectedColumns, setSelectedColumns] = useState(data.selectedColumns || []);
  const [columnOptions, setColumnOptions] = useState([]);

  const loadData = useCallback(() => {
    fetch(csvData)
      .then(response => response.text())
      .then(csv => {
        const rows = csv.split('\n').map(row => row.split(','));
        const headers = rows[0];
        const dataRows = rows.slice(1).filter(row => row.length === headers.length);

        const processedData = dataRows.map(row => {
          const obj = {};
          headers.forEach((header, index) => {
            obj[header] = parseFloat(row[index]);
          });
          return obj;
        });

        setPlotData(processedData);
        setColumnOptions(headers.map(header => ({ value: header, label: header })));
      });
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleColumnChange = useCallback((selectedOptions) => {
    const columns = selectedOptions.map(option => option.value);
    setSelectedColumns(columns);

    const newDimensions = columns.map(column => ({
      range: [Math.min(...plotData.map(d => d[column])), Math.max(...plotData.map(d => d[column]))],
      label: column,
      values: plotData.map(d => d[column])
    }));

    setDimensions(newDimensions);
    setData({ selectedColumns: columns, dimensions: newDimensions });
  }, [plotData, setData]);

  const handleSaveLayout = useCallback(() => {
    if (layoutName.trim() !== '') {
      const newSavedLayouts = [
        ...savedLayouts,
        { name: layoutName, dimensions, selectedColumns }
      ];
      setSavedLayouts(newSavedLayouts);
      setData({ savedLayouts: newSavedLayouts });
      setLayoutName('');
    }
  }, [layoutName, dimensions, selectedColumns, savedLayouts, setData]);

  const handleLayoutSelect = useCallback((option) => {
    const selected = option.value;
    const layout = savedLayouts.find(layout => layout.name === selected);
    if (layout) {
      setSelectedLayout(selected);
      setDimensions(layout.dimensions);
      setSelectedColumns(layout.selectedColumns);
      setData({ selectedLayout: selected, dimensions: layout.dimensions, selectedColumns: layout.selectedColumns });
    }
  }, [savedLayouts, setData]);

  return (
    <div>
      <Grid container spacing={2} alignItems="center" justifyContent="flex-start">
        <Grid item>
          <ReactSelect
            isMulti
            options={columnOptions}
            value={selectedColumns.map(column => ({ value: column, label: column }))}
            onChange={handleColumnChange}
          />
        </Grid>
        <Grid item>
          <TextField
            label="Layout Name"
            value={layoutName}
            onChange={(e) => setLayoutName(e.target.value)}
            variant="outlined"
            style={{ margin: '16px', minWidth: '200px' }}
          />
        </Grid>
        <Grid item>
          <ReactSelect
            options={savedLayouts.map(layout => ({ value: layout.name, label: layout.name }))}
            value={selectedLayout ? { value: selectedLayout, label: selectedLayout } : null}
            onChange={handleLayoutSelect}
          />
        </Grid>
      </Grid>
      <Plot
        data={[
          {
            type: 'parcoords',
            dimensions: dimensions,
            line: {
              color: plotData.map(d => d[selectedColumns[0]]),
              colorscale: 'Viridis'
            }
          }
        ]}
        layout={{
          autosize: true,
          margin: { t: 50, b: 50, l: 50, r: 50 },
        }}
        useResizeHandler={true}
        style={{ width: '100%', height: '600px' }}
      />
    </div>
  );
};

export default ParallelCoordinatesPlot;